import math
from sklearn.model_selection import train_test_split
from sklearn.neighbors import KNeighborsClassifier


def scale_columns(rows):
    rows = list(rows)
    if not rows:
        return []
    if len(rows[0]) == 0:
        return [[] for _ in rows]

    columns = list(zip(*rows))
    scaled_columns = []

    for column in columns:
        smallest = min(column)
        largest = max(column)

        if largest == smallest:
            scaled_columns.append([0.0 for _ in column])
        else:
            scaled_columns.append([
                (value - smallest) / (largest - smallest)
                for value in column
            ])

    return [list(row) for row in zip(*scaled_columns)]


def nearest_label(X, y, point):
    best_index = 0
    best_distance = math.dist(X[0], point)

    for index in range(1, len(X)):
        distance = math.dist(X[index], point)
        if distance < best_distance:
            best_distance = distance
            best_index = index

    return y[best_index]


def knn_predict(X, y, rows, k):
    if k > len(X):
        raise ValueError("k cannot be larger than the number of known stars")

    model = KNeighborsClassifier(n_neighbors=k)
    model.fit(X, y)
    return list(model.predict(rows))


