    best_distance = math.dist(X[0], point)
    for i in range(1, len(X)):
        distance = math.dist(X[i], point)
        if distance < best_distance:
            best_distance = distance
            best_index = i
    return y[best_index]


def knn_predict(X, y, rows, k):
    if k > len(X):
        raise ValueError(f"Cannot use {k} neighbours with only {len(X)} known stars.")

    model = KNeighborsClassifier(n_neighbors=k)
    model.fit(X, y)
    return model.predict(rows).tolist()


def star_accuracy(X, y):
    scaled_X = scale_columns(X)
    X_train, X_test, y_train, y_test = train_test_split(
        scaled_X, y, test_size=0.25, random_state=0
    )

    model = KNeighborsClassifier(n_neighbors=3)
    model.fit(X_train, y_train)
    predictions = model.predict(X_test)

    correct = sum(1 for actual, predicted in zip(y_test, predictions) if actual == predicted)
    return correct / len(y_test)
